using CoreModels;
using Microsoft.EntityFrameworkCore;
namespace DataAccessLayer;
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options) { public DbSet<AppUser> AppUsers => Set<AppUser>(); public DbSet<Project> Projects => Set<Project>(); public DbSet<Release> Releases => Set<Release>(); public DbSet<ScanResult> ScanResults => Set<ScanResult>(); public DbSet<ScanFinding> ScanFindings => Set<ScanFinding>(); public DbSet<RiskScore> RiskScores => Set<RiskScore>(); public DbSet<PolicyDecision> PolicyDecisions => Set<PolicyDecision>(); public DbSet<PipelineRun> PipelineRuns => Set<PipelineRun>(); public DbSet<Policy> Policies => Set<Policy>(); public DbSet<PolicyRule> PolicyRules => Set<PolicyRule>(); public DbSet<AuditLog> AuditLogs => Set<AuditLog>(); protected override void OnModelCreating(ModelBuilder b) { b.HasDefaultSchema("dbo"); b.Entity<AppUser>().ToTable("AppUsers").HasIndex(x => x.Email).IsUnique(); b.Entity<Project>().ToTable("Projects"); b.Entity<Release>().ToTable("Releases"); b.Entity<ScanResult>().ToTable("ScanResults"); b.Entity<ScanFinding>().ToTable("ScanFindings"); b.Entity<RiskScore>().ToTable("RiskScores").Property(x => x.Score).HasColumnName("RiskScore"); b.Entity<PolicyDecision>().ToTable("PolicyDecisions"); b.Entity<PipelineRun>().ToTable("PipelineRuns"); b.Entity<Policy>().ToTable("Policies"); b.Entity<PolicyRule>().ToTable("PolicyRules"); b.Entity<AuditLog>().ToTable("AuditLogs"); } }
public interface IRepository<T> where T : class { IQueryable<T> Query(); Task<T?> GetAsync(long id); Task AddAsync(T entity); void Update(T entity); Task SaveAsync(); }
public class Repository<T>(AppDbContext db) : IRepository<T> where T : class { public IQueryable<T> Query() => db.Set<T>(); public Task<T?> GetAsync(long id) => db.Set<T>().FindAsync(id).AsTask(); public Task AddAsync(T e) => db.Set<T>().AddAsync(e).AsTask(); public void Update(T e) => db.Set<T>().Update(e); public Task SaveAsync() => db.SaveChangesAsync(); }
